import { Controller, Get, UseGuards } from '@nestjs/common';
import { JwtAuthGuard } from './jwt-auth.guard';
import { RolesGuard } from './roles.guard';
import { Roles } from './roles.decorator';

@Controller('admin')
export class AdminController {
  // BUG: RolesGuard is listed (and therefore runs) before JwtAuthGuard,
  // so it reads request.user before authentication ever attaches it.
  @Get('users')
  @Roles('admin')
  @UseGuards(RolesGuard, JwtAuthGuard)
  getUsers() {
    return [
      { id: 'u1', email: 'alice@example.com', role: 'admin' },
      { id: 'u2', email: 'bob@example.com', role: 'admin' },
    ];
  }
}
